CREATE TABLE IF NOT EXISTS money_imc_visit (line_key CHAR(64) NOT NULL, service_date DATE NOT NULL, code VARCHAR(20) NOT NULL, claim DECIMAL(15,2) NOT NULL, record_ciphertext MEDIUMTEXT NOT NULL, uploaded_at DATETIME NOT NULL, uploaded_by CHAR(36) NOT NULL, PRIMARY KEY (line_key), KEY money_imc_visit_date (service_date), CONSTRAINT money_imc_visit_person_fk FOREIGN KEY (uploaded_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS money_imc_rep (rep_no VARCHAR(30) NOT NULL, trans_id VARCHAR(30) NOT NULL, item_no INT NOT NULL, service_date DATE NOT NULL, claim DECIMAL(15,2) NOT NULL, paid DECIMAL(15,2) NOT NULL, record_ciphertext MEDIUMTEXT NOT NULL, uploaded_at DATETIME NOT NULL, uploaded_by CHAR(36) NOT NULL, PRIMARY KEY (rep_no, trans_id, item_no), KEY money_imc_rep_date (service_date), CONSTRAINT money_imc_rep_person_fk FOREIGN KEY (uploaded_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
